"use client";
import { cn } from "@/lib/utils";
import { panel as surfacePanel } from "@/lib/takt-surface";

import { useState } from "react";
import { motion, useReducedMotion } from "motion/react";

export function JellySlider({
  className,
  label = "Elasticity",
  onChange,
}: {
  className?: string;
  label?: string;
  onChange?: (value: number) => void;
}) {
  const [level, setLevel] = useState(45);
  const [drag, setDrag] = useState(false);
  const reduced = useReducedMotion();
  return (
    <label className={cn(surfacePanel + " grid w-52 gap-3", className)}>
      <span className="flex justify-between">
        {label}
        <output>{level}%</output>
      </span>
      <span className="relative mx-2 h-5 rounded-full has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-4">
        <span className="absolute inset-x-0 top-2 h-1 rounded bg-muted-foreground/40" />
        <span
          aria-hidden
          className="absolute inset-x-0 top-2 h-1 origin-left rounded bg-primary"
          style={{ transform: "scaleX(" + level / 100 + ")" }}
        />
        {drag && (
          <span
            aria-hidden
            className="absolute bottom-7 -translate-x-1/2 rounded-md bg-primary px-1.5 py-1 font-mono text-[10px] text-primary-foreground motion-safe:animate-in motion-safe:slide-in-from-bottom-1"
            style={{ left: level + "%" }}
          >
            {level}
          </span>
        )}
        <motion.span
          style={{ left: level + "%", x: "-50%" }}
          animate={{
            scaleX: drag && !reduced ? 1.22 : 1,
            scaleY: drag && !reduced ? 0.8 : 1,
          }}
          transition={
            reduced
              ? { duration: 0 }
              : { type: "spring", stiffness: 215, damping: 24 }
          }
          className="absolute top-0 size-5 rounded-full bg-primary"
        />
        <input
          type="range"
          className="absolute inset-0 w-full opacity-0"
          aria-label={label}
          value={level}
          onPointerDown={(e) => {
            if (e.isPrimary && e.button === 0) {
              e.currentTarget.setPointerCapture(e.pointerId);
              setDrag(true);
            }
          }}
          onLostPointerCapture={() => setDrag(false)}
          onPointerUp={() => setDrag(false)}
          onPointerCancel={() => setDrag(false)}
          onBlur={() => setDrag(false)}
          onChange={(e) => {
            setLevel(+e.target.value);
            onChange?.(+e.target.value);
          }}
        />
      </span>
    </label>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
